	private int storeInstance;

	@BeforeEach
	public void setUp() throws Exception {
		previousProperties = new HashMap<>();
		for (String property : new String[] { "rdf4j.lmdb.csrCache.minProbes", "rdf4j.lmdb.csrCache.maxGenerations",
				"rdf4j.lmdb.csrCache.snapshotServing" }) {
			previousProperties.put(property, System.getProperty(property));
		}
		System.setProperty("rdf4j.lmdb.csrCache.minProbes", "1");
		openStore();
	}

	@AfterEach
	public void tearDown() throws Exception {
		for (Map.Entry<String, String> entry : previousProperties.entrySet()) {
			if (entry.getValue() == null) {
				System.clearProperty(entry.getKey());
			} else {
				System.setProperty(entry.getKey(), entry.getValue());
			}
		}
		closeStore();
	}

	private void openStore() throws Exception {
		closeStore();
		File dir = new File(dataDir, "store-" + storeInstance++);
		tripleStore = new TripleStore(dir, new LmdbStoreConfig("spoc,posc"), null);
		storeTxnStarted = new java.util.concurrent.atomic.AtomicBoolean(false);
		cache = new LmdbCsrAdjacencyCache(tripleStore, storeTxnStarted);
		tripleStore.setCsrCommitListener(cache.commitListener());
		LmdbCsrAdjacencyCache.GENERATIONS_RETAINED.set(0);
		LmdbCsrAdjacencyCache.GENERATIONS_PRUNED.set(0);
		LmdbCsrAdjacencyCache.SNAPSHOT_HITS.set(0);
	}

	private void closeStore() throws Exception {
		if (cache != null) {
			cache.close();
			cache = null;
		}
		if (tripleStore != null) {
			tripleStore.close();
			tripleStore = null;
		}
	}

	private void commitWithDelta() throws Exception {
		tripleStore.commit();
		cache.applyCommittedDelta(tripleStore.drainCsrCommitDelta());
	}

	private void buildEntry(long pred, int direction, boolean explicit) throws Exception {
		try (Txn txn = tripleStore.getTxnManager().createReadTxn()) {
			cache.recordProbes(pred, direction, explicit, 1_000_000, txn);
		}
	}

	private void loadPredA() throws Exception {
		tripleStore.startTransaction();
		for (long subj = 100; subj < 110; subj++) {
			tripleStore.storeTriple(subj, PRED_A, 1000 + subj, 0, true);
		}
		commitWithDelta();
	}

	@Test
	public void pinnedReaderSeesPreCommitGenerationWhileLatestSeesMerged() throws Exception {
		loadPredA();
		buildEntry(PRED_A, LmdbCsrAdjacencyCache.BY_SUBJECT, true);
		CsrEntry preCommit = cache.lookup(PRED_A, LmdbCsrAdjacencyCache.BY_SUBJECT, true);
		assertThat(preCommit).isNotNull();

		try (Txn pinned = tripleStore.getTxnManager().createReadTxnPinned(tripleStore::getDataRevision)) {
			long snapshot = pinned.snapshotRevision();
			assertThat(snapshot).isEqualTo(tripleStore.getDataRevision());

			tripleStore.startTransaction();
			tripleStore.storeTriple(150, PRED_A, 5000, 0, true);
			tripleStore.removeTriplesByContext(100, PRED_A, 1100, 0, true, q -> {
			});
			commitWithDelta();

			// the pinned snapshot is served by the retained pre-commit generation — the very same instance
			CsrEntry snapshotEntry = cache.lookup(PRED_A, LmdbCsrAdjacencyCache.BY_SUBJECT, true, snapshot);
			assertThat(snapshotEntry).isSameAs(preCommit);
			assertThat(snapshotEntry.hasInRun(100, 1100, -1)).isTrue();
			assertThat(snapshotEntry.hasInRun(150, 5000, -1)).isFalse();

			// latest lookups see the merged entry
			CsrEntry latest = cache.lookup(PRED_A, LmdbCsrAdjacencyCache.BY_SUBJECT, true);
			assertThat(latest).isNotSameAs(preCommit);
			assertThat(latest.hasInRun(100, 1100, -1)).isFalse();
			assertThat(latest.hasInRun(150, 5000, -1)).isTrue();

			assertThat(LmdbCsrAdjacencyCache.GENERATIONS_RETAINED.get()).isEqualTo(1);
			assertThat(LmdbCsrAdjacencyCache.SNAPSHOT_HITS.get()).isGreaterThan(0);
		}
	}

	@Test
	public void noRetentionWithoutPinnedReaders() throws Exception {
		loadPredA();
		buildEntry(PRED_A, LmdbCsrAdjacencyCache.BY_SUBJECT, true);
		long oldRevision = tripleStore.getDataRevision();

		tripleStore.startTransaction();
		tripleStore.storeTriple(150, PRED_A, 5000, 0, true);
		commitWithDelta();

		assertThat(LmdbCsrAdjacencyCache.GENERATIONS_RETAINED.get()).isZero();
		assertThat(cache.lookup(PRED_A, LmdbCsrAdjacencyCache.BY_SUBJECT, true, oldRevision)).isNull();
		assertThat(cache.lookup(PRED_A, LmdbCsrAdjacencyCache.BY_SUBJECT, true)).isNotNull();
	}

	@Test
	public void generationsPrunedAfterReaderCloses() throws Exception {
		loadPredA();
		buildEntry(PRED_A, LmdbCsrAdjacencyCache.BY_SUBJECT, true);

		long snapshot;
		try (Txn pinned = tripleStore.getTxnManager().createReadTxnPinned(tripleStore::getDataRevision)) {
			snapshot = pinned.snapshotRevision();
			tripleStore.startTransaction();
			tripleStore.storeTriple(150, PRED_A, 5000, 0, true);
			commitWithDelta();
			assertThat(cache.lookup(PRED_A, LmdbCsrAdjacencyCache.BY_SUBJECT, true, snapshot)).isNotNull();
		}
		// the reader is gone; the next applied commit prunes the retained generation
		tripleStore.startTransaction();
		tripleStore.storeTriple(151, PRED_A, 5001, 0, true);
		commitWithDelta();

		assertThat(LmdbCsrAdjacencyCache.GENERATIONS_PRUNED.get()).isGreaterThan(0);
		assertThat(cache.lookup(PRED_A, LmdbCsrAdjacencyCache.BY_SUBJECT, true, snapshot)).isNull();
		assertThat(cache.lookup(PRED_A, LmdbCsrAdjacencyCache.BY_SUBJECT, true)).isNotNull();
	}

